const URL='https://6615ddf3b8b8e32ffc7bdc0a.mockapi.io/product'
const list =document.getElementById('list')
const cart = document.getElementById('cart')

let cartArr = [] // array of items which will be on cart

function getProducts(){ //getting all prodtucts from API
    return new Promise((resolve, reject)=>{
        fetch(URL)
        .then(response => {
            if(response.ok){
                resolve(response.json())
            }else reject(new Error('problem with api'))
        })
    })
}

function setData(key ,el){ //add data (that will be 4 cart & product list)
    localStorage.setItem(key,JSON.stringify(el))
}
function getData(key){ //get data (that will be also 4 cart & product list)
    return JSON.parse(localStorage.getItem(key))
}

function loadData(){
    let storedCart = getData('cart')
    console.log(storedCart);
    if(storedCart){
        storedCart.forEach(el => layoutCart(el))
    }
}
function layoutProduct(el) {
    const listProduct = document.createElement('div');
    listProduct.classList.add('list-product');

    const imageContainer = document.createElement('div');
    imageContainer.classList.add('product__image-container');

    const image = document.createElement('img');
    image.classList.add('product__image');
    image.src = el.photo;
    image.alt = 'product';

    const overlayButton = document.createElement('button');
    overlayButton.classList.add('product__overlay-btn', 'btn');
    overlayButton.textContent = 'Быстрый просмотр';

    const infoContainer = document.createElement('div');
    infoContainer.classList.add('product__info');

    const priceParagraph = document.createElement('p');
    priceParagraph.classList.add('product__price');
    priceParagraph.textContent = el.price;

    const nameHeading = document.createElement('h3');
    nameHeading.classList.add('product__name');
    nameHeading.textContent = el.name;

    const addButton = document.createElement('button');
    addButton.classList.add('product__btn', 'btn');
    addButton.textContent = 'Добавить в Корзину';
    addButton.addEventListener('click', function() {
        layoutCart(el);
    });

    listProduct.appendChild(imageContainer);
    imageContainer.appendChild(image);
    imageContainer.appendChild(overlayButton);
    listProduct.appendChild(infoContainer);
    infoContainer.appendChild(priceParagraph);
    infoContainer.appendChild(nameHeading);
    listProduct.appendChild(addButton);

    list.appendChild(listProduct);
}


function layoutCart(el){
    const productInCart = document.createElement('div')
    productInCart.classList.add('product');
    const nameInCart = document.createElement('p')
    nameInCart.id = 'nameInCart';
    nameInCart.classList.add('nameInCart');
    nameInCart.innerHTML=el.name
    const priceInCart = document.createElement('p');
    priceInCart.id = 'price';
    priceInCart.classList.add('price');
    priceInCart.innerHTML = el.price
    const photoInCart = document.createElement('img');
    photoInCart.id = 'photo';
    photoInCart.classList.add('photo');
    photoInCart.src = `${el.photo}`
    cart.appendChild(productInCart)
    productInCart.appendChild(photoInCart);
    productInCart.appendChild(nameInCart);
    productInCart.appendChild(priceInCart);
    cartArr.push(el)
    setData('cart',cartArr)

}

getProducts()
.then(products => products.forEach(el=>layoutProduct(el)))
.then()

window.addEventListener('load',function(){
    loadData()
})

// Создаем список товаров
const productList = document.createElement('ul');
productList.className = 'cart__list';
// Здесь вы можете добавить элементы списка товаров вручную или сгенерировать их с помощью JavaScript


cart.appendChild(productList);

// Добавляем обработчик события наведения мыши на корзину
cart.addEventListener('mouseover', showCart);

// Функция, которая показывает корзину с товарами
function showCart() {
    productList.style.display = 'block';
}
